using System.IO;
using System.Text.Json;
namespace CamoTracker;
static class ModelTests
{
 public static int Run()
 {
  try
  {
   void Assert(bool value,string message){if(!value)throw new Exception(message);}
   var t=new Tracker(null);Assert(t.Data.Weapons.Count(w=>w.Category!="模式精通")>=33,"launch weapons retained");Assert(t.Data.Weapons.Where(w=>w.Category!="模式精通").Sum(w=>w.Challenges.Count(c=>c.Kind=="special"))>=99,"launch specials retained");
   var launch=t.Data.Weapons.Where(w=>w.Category!="模式精通").ToList();Assert(DataCatalog.Active.WeaponImages.Count>=33&&launch.Where(w=>WeaponArt.Info(w)!=null).All(w=>w.MaxLevel>0),"official mappings and known max levels");Assert(launch.Where(w=>WeaponArt.Info(w)!=null).Select(w=>WeaponArt.Info(w)!.Image).Distinct().Count()>=33,"launch thumbnails are distinct");Assert(WeaponArt.Info(new Weapon{Name="M4"})==null,"custom guns do not silently reuse another image");
   Assert(Bilingual.WeaponZh(launch.First(w=>w.Name=="VEL 46"))=="威尔46"&&Bilingual.WeaponZh(launch.First(w=>w.Name=="Axion"))=="阿克西恩"&&Bilingual.WeaponZh(launch.First(w=>w.Name=="Hyeon Burst"))=="玄铁（点射型）","official Simplified Chinese gun names, not categories");
   Assert(launch.SelectMany(w=>w.Challenges).Where(c=>c.Kind=="special").All(c=>Bilingual.CamoZh(c)!=c.Name),"99 special names have Chinese reference translations");Assert(t.Data.Weapons.SelectMany(w=>w.Challenges).All(c=>Bilingual.RuleEn(c).Length>0),"builtin challenges have English rules");Assert(Bilingual.Camo(launch.First(w=>w.Name=="M4").Challenges.First(c=>c.Kind=="special")).Contains("万象 · Myriad"),"bilingual camo label");Assert(Bilingual.RuleEn(new Challenge{Source="用户自定义",SourceRule="old official text"})=="","edited rule cannot retain stale English translation");
   Assert(t.Data.UnlockEffects&&!t.Data.UnlockSound,"unlock animation default, audio opt-in");t.Data.UnlockEffects=false;t.Data.UnlockSound=true;var effectPrefs=Tracker.Parse(JsonSerializer.Serialize(t.Data));Assert(!effectPrefs.UnlockEffects&&effectPrefs.UnlockSound,"effect preferences roundtrip");
   Assert(t.Data.MainDesign=="classic","existing layout remains default");t.Data.MainDesign="armory";Assert(Tracker.Parse(JsonSerializer.Serialize(t.Data)).MainDesign=="armory","main design preference persists");t.Data.MainDesign="classic";
   using(var wav=UnlockAudio.Open()){using var reader=new BinaryReader(wav);Assert(System.Text.Encoding.ASCII.GetString(reader.ReadBytes(4))=="RIFF","original audio embedded");reader.ReadInt32();Assert(System.Text.Encoding.ASCII.GetString(reader.ReadBytes(4))=="WAVE"&&wav.Length is >40000 and <200000,"bounded PCM reward cue");}
   var report=new Tracker(null);Assert(ProgressSummary.Collection(report.Data).Done==0&&ProgressSummary.Collection(report.Data).Total==report.Data.Weapons.Where(w=>w.Category!="模式精通").Sum(w=>w.Challenges.Count),"collection excludes global mode records");var reportGun=report.CurrentWeapon;var reportGold=reportGun.Challenges.First(c=>c.Kind=="gold");report.MarkUnlocked(reportGun,reportGold,true);Assert(ProgressSummary.Collection(report.Data).Done==12&&ProgressSummary.Route(report.Data,"gold").Done==1,"global collection counts inferred prerequisites once");Assert(Math.Abs(ProgressSummary.Route(report.Data,"gold").Remaining-100.0*(ProgressSummary.Route(report.Data,"gold").Total-1)/ProgressSummary.Route(report.Data,"gold").Total)<.001,"remaining route percentage");var unknown=new Challenge();Assert(ProgressSummary.Percent(unknown)==null,"unknown percentage not zero");unknown.ProgressKnown=true;Assert(ProgressSummary.Percent(unknown)==0,"known zero percentage");unknown.RequirementUnverified=true;unknown.Count=unknown.Target;Assert(ProgressSummary.Percent(unknown)==null,"uncertain percentage excluded");
   var han=t.CurrentWeapon;var smoke=t.Current;Assert(!smoke.ProgressKnown&&!smoke.Done,"unknown is not zero");t.Change(5);Assert(smoke.Count==5&&smoke.ProgressKnown,"record count");t.Undo();Assert(!t.Current.ProgressKnown&&t.Current.Count==0,"undo known flag");
   t.Change(1);t.Data.MainDesign="arena";t.Undo();Assert(t.Data.MainDesign=="arena"&&t.Current.Count==0,"undo progress preserves chosen design");t.Data.MainDesign="classic";
   han=t.CurrentWeapon;smoke=t.Current;var gold=han.Challenges.First(c=>c.Kind=="gold");Assert(Eligibility.Reason(t.Data,han,gold)!=null,"gold prerequisites");t.MarkUnlocked(han,gold,true);Assert(han.Challenges.Where(c=>c.Kind is "military" or "special").All(c=>c.Done),"historical gold implies prerequisites");
   var platinum=han.Challenges.First(c=>c.Kind=="platinum");Assert(Eligibility.Reason(t.Data,han,platinum)!=null,"class gold gate");foreach(var w in t.Data.Weapons.Where(w=>w.Category==han.Category))t.MarkUnlocked(w,w.Challenges.First(c=>c.Kind=="gold"),true);Assert(Eligibility.Reason(t.Data,han,platinum)==null,"class gate satisfied");
   var harmonic=han.Challenges.First(c=>c.Kind=="harmonic");Assert(Eligibility.Reason(t.Data,han,harmonic)!=null,"33 platinum gate");
   var fresh=new Tracker(null);var m4=fresh.Data.Weapons.First(w=>w.Name=="M4");foreach(var c in m4.Challenges.Where(c=>c.Kind=="military"))fresh.MarkUnlocked(m4,c,true);var specials=m4.Challenges.Where(c=>c.Kind=="special").ToList();foreach(var c in specials)c.OpenConfirmed=true;fresh.RecordTotal(m4,specials[0],15);fresh.RecordTotal(m4,specials[1],19);Assert(Recommendations.ForWeapon(fresh.Data,m4)==specials[1],"closest eligible objective");
   var closest=ProgressSummary.Closest(fresh.Data);Assert(closest.Count==1&&closest[0].weapon==m4&&closest[0].challenge==specials[1],"global nearest ranks ready known progress once per weapon");var blocked=m4.Challenges.First(c=>c.Kind=="gold");blocked.ProgressKnown=true;blocked.Count=blocked.Target-1;Assert(ProgressSummary.Closest(fresh.Data).All(row=>row.challenge!=blocked),"locked high percentage is not nearest ready target");
   fresh.SetSession(m4,true);fresh.SetSession(fresh.Data.Weapons.First(w=>w.Name=="HAN 86"),true);var plan=Recommendations.Next(fresh.Data,new HashSet<string>(),true);Assert(plan.Count==2&&plan[0].weapon==m4,"session follows user order");var json=JsonSerializer.Serialize(fresh.Data);Assert(Tracker.Parse(json).SessionWeapons.Count==2,"session persistence");fresh.SetSession(m4,false);Assert(Recommendations.Next(fresh.Data,new HashSet<string>(),true).Count==1,"unselect session");
   m4.FocusChallengeId=specials[0].Id;Assert(Recommendations.ForWeapon(fresh.Data,m4)==specials[0],"explicit objective overrides nearest");fresh.MarkUnlocked(m4,specials[0],true);Assert(Recommendations.ForWeapon(fresh.Data,m4)!=specials[0],"completed focus advances");
   var empty=new Tracker(null);empty.Data.SessionConfigured=true;Assert(Recommendations.Next(empty.Data,new HashSet<string>(),true).Count==0,"explicit empty plan stays empty");foreach(var w in empty.Data.Weapons.Take(5))empty.SetSession(w,true);bool limited=false;try{empty.SetSession(empty.Data.Weapons[5],true);}catch(InvalidOperationException){limited=true;}Assert(limited&&empty.Data.SessionWeapons.Count==5,"five weapon limit");
   var red=fresh.Data.Weapons.First(w=>w.Name=="HAN 86").Challenges.First(c=>c.Name=="Red");red.Count=red.Target;red.ProgressKnown=true;Assert(!red.Done,"conflicting source cannot complete");fresh.MarkUnlocked(fresh.Data.Weapons.First(w=>w.Name=="HAN 86"),red,true);Assert(red.Done,"actual historical unlock overrides uncertain text");
   var h=fresh.Data.Weapons.First(w=>w.Name=="HAN 86");var terminus=h.Challenges.First(c=>c.ArtKey=="terminus");h.LevelKnown=true;h.Prestige=1;h.WeaponLevel=71;Assert(Eligibility.Reason(fresh.Data,h,terminus)!=null,"prestige not max");h.WeaponLevel=72;Assert(Eligibility.Reason(fresh.Data,h,terminus)==null,"prestige max");var scatter=h.Challenges.First(c=>c.ArtKey=="scatter");h.Prestige=2;h.WeaponLevel=149;Assert(Eligibility.Reason(fresh.Data,h,scatter)!=null,"master 149");h.WeaponLevel=150;Assert(Eligibility.Reason(fresh.Data,h,scatter)==null,"master 150");
   var old=new TrackerData{Weapons=[new Weapon{Name="HAN 86",Challenges=[new Challenge{Name="Smoke · 烟雾",Count=7,Target=20,Source=Tracker.Official}]}]};old.SelectedWeapon=old.Weapons[0].Id;old.SelectedChallenge=old.Weapons[0].Challenges[0].Id;Catalog.Upgrade(old);Assert(old.Weapons.First(w=>w.Name=="HAN 86").Challenges.Any(c=>c.Count==7&&c.ProgressKnown),"legacy progress retained");
   var path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"camo-tests-"+Guid.NewGuid()+".json");try{var disk=new Tracker(path);disk.Change(8);Assert(new Tracker(path).Current.Count==8,"disk roundtrip");disk.Change(1);Assert(File.Exists(path+".bak"),"backup");File.WriteAllText(path,"invalid");var recovered=new Tracker(path);Assert(recovered.Notice.Contains("损坏"),"corrupt recovery");}finally{foreach(var f in Directory.GetFiles(System.IO.Path.GetDirectoryName(path)!,System.IO.Path.GetFileName(path)+"*"))File.Delete(f);}
   var guarded=new Tracker(null);var guardedGun=guarded.CurrentWeapon;var lockedGold=guardedGun.Challenges.First(c=>c.Kind=="gold");bool denied=false;try{guarded.CompleteRun(guardedGun,lockedGold);}catch(InvalidOperationException){denied=true;}Assert(denied&&!lockedGold.Done,"daily unlock rejects unmet gates");denied=false;try{guarded.RecordRunTotal(guardedGun,lockedGold,lockedGold.Target);}catch(InvalidOperationException){denied=true;}Assert(denied&&lockedGold.Count==0,"daily totals cannot bypass gates");
   var other=guarded.Data.Weapons.First(w=>w.Id!=guardedGun.Id);var otherBefore=JsonSerializer.Serialize(other);var firstPrestige=guardedGun.Challenges.First(c=>c.Kind=="prestige");guarded.MarkUnlocked(guardedGun,firstPrestige,true);var milestone=guardedGun.Challenges.First(c=>c.Kind=="gold");guarded.RestoreTo(guardedGun,milestone);Assert(guardedGun.Challenges.Where(c=>c.Kind is "military" or "special" or "gold").All(c=>c.Done)&&!guardedGun.Challenges.First(c=>c.Kind=="platinum").Done&&firstPrestige.Done,"restore milestone preserves independent prestige branch");Assert(JsonSerializer.Serialize(other)==otherBefore,"restore does not edit other guns");var lower=guardedGun.Challenges.First(c=>c.Kind=="military");guarded.RestoreTo(guardedGun,lower);Assert(!milestone.Done&&lower.Done,"restore can correct backwards");guarded.Undo();Assert(guarded.CurrentWeapon.Challenges.First(c=>c.Kind=="gold").Done,"restore is undoable");
   var levelGuard=new Tracker(null);var militaryReward=levelGuard.CurrentWeapon.Challenges.First(c=>c.Kind=="military");denied=false;try{levelGuard.CompleteRun(levelGuard.CurrentWeapon,militaryReward);}catch(InvalidOperationException){denied=true;}Assert(denied,"military reward requires recorded weapon level");levelGuard.CurrentWeapon.LevelKnown=true;levelGuard.CurrentWeapon.WeaponLevel=militaryReward.RequiredWeaponLevel;Assert(Eligibility.Reason(levelGuard.Data,levelGuard.CurrentWeapon,militaryReward)==null,"military level gate satisfied");
   DataUpdateTests.Run();
   File.WriteAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"test-results.txt"),"PASS: daily prerequisite enforcement / milestone restore branches and undo / data pack validation / schema / ZIP paths / merge / custom edits / new bilingual art / gates / atomic failure and crash recovery; 33 official weapon mappings/Chinese names/max levels, 99 bilingual specials, English rules, original WAV, effect settings, global percentages/remaining/nearest/exclusions, unknown progress, history, dependencies, recommendations, session order/persistence/removal/limit, source conflict, prestige boundaries, migration, disk backup/recovery");return 0;
  }
  catch(Exception e){File.WriteAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"test-results.txt"),"FAIL: "+e);return 1;}
 }
